import{z as o,x as l,o as a,c as s,q as e,j as r,D as A,d as t,s as n,S as i}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"实验设计","description":"","frontmatter":{"title":"实验设计","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/bx-experiment-design.md","filePath":"econ/bx-experiment-design.md","lastUpdated":1791063341000}'),p={name:"econ/bx-experiment-design.md"};function d(c,E,m,_,h,D){const B=l("Mermaid");return a(),s("div",null,[E[2]||(E[2]=e('<h1 id="实验设计" tabindex="-1">实验设计 <a class="header-anchor" href="#实验设计" aria-label="Permalink to &quot;实验设计&quot;">​</a></h1><div class="epigraph"><p>实验的特权是把机制单独拎出来；代价是每一个想要的结果都能被协议造出来。设计规范不是美德清单，是防止自己骗自己的工程。</p><footer>—— 据 Smith, American Economic Review, 1982 及现行预注册惯例整理</footer></div><p><a href="/econ/bx-social-preferences">上一课</a>把「拒绝免费的钱」参数化成 \\(\\alpha\\)、\\(\\beta\\) 与意图维度。风险、时间、社会三块行为区域到此过完，本单元转到方法：这些数字是怎么测出来的，又怎么防止测错。<a href="/econ/experimental-methods">实验经济学方法</a>已在主干钉了两条底线：诱导价值隔离机制，支付过小就退化成廉价交谈。本课在其上补一个完整的设计协议——处理结构、随机化、激励、功效、预注册五步，目标是把「防假阳性」从品德要求变成流程。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>行为实验的效应量普遍不大，而协议自由度极大：题目顺序、报酬方式、被试池、实验者在场，每一项都能移动结果。同一个假设换个顺序就能翻转符号——这既是威胁，也是证据：<a href="/econ/framing-effects">框架效应</a>本身就是这样被测出来的。缺口落在方法层：一个结论要站住，必须先钉死协议的哪些自由度、报告哪些检查，再谈效应。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>五步协议。(1) 处理结构：被试间（每人只见一种处理，组间干净，无 carryover）还是被试内（每人过全部处理，功效高数倍，但要拉丁方平衡顺序、加清洗段）。风险题与公平题混排是典型事故：损失框定污染随后的公平判断。(2) 随机化：被试间随机分配生成可比组并报平衡表；被试内随机化顺序与题目呈现。(3) 激励协议：真实激励为默认；风险与时间偏好用「多题作答、随机抽一轮兑现」，把财富效应压到只发生一次；假设性问答只许出现在预实验。(4) 功效：先定最小可检测效应与检验水平，反推每组样本量——行为实验常见效应量在 \\(d\\approx0.3\\)–\\(0.5\\) 一带，80% 功效下每组需几十到上百人。(5) 预注册：假设、排除规则、多重比较修正，在看数据之前冻结。</p>',7)),(a(),r(i,null,{default:A(()=>[n(B,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E5%81%87%E8%AE%BE%E4%B8%8E%E6%9C%80%E5%B0%8F%E5%8F%AF%E6%A3%80%E6%B5%8B%E6%95%88%E5%BA%94%22%5D%20--%3E%20PWR%5B%22%E5%8A%9F%E6%95%88%E8%AE%A1%E7%AE%97%E5%AE%9A%E6%AF%8F%E7%BB%84%E4%BA%BA%E6%95%B0%22%5D%0A%20%20PWR%20--%3E%20DES%7B%22%E8%A2%AB%E8%AF%95%E9%97%B4%E8%BF%98%E6%98%AF%E8%A2%AB%E8%AF%95%E5%86%85%3F%22%7D%0A%20%20DES%20--%3E%7C%E8%A2%AB%E8%AF%95%E9%97%B4%7C%20R1%5B%22%E9%9A%8F%E6%9C%BA%E5%88%86%E9%85%8D%E5%8A%A0%E5%B9%B3%E8%A1%A1%E8%A1%A8%22%5D%0A%20%20DES%20--%3E%7C%E8%A2%AB%E8%AF%95%E5%86%85%7C%20R2%5B%22%E6%8B%89%E4%B8%81%E6%96%B9%E5%B9%B3%E8%A1%A1%E9%A1%BA%E5%BA%8F%E5%8A%A0%E6%B8%85%E6%B4%97%E6%AE%B5%22%5D%0A%20%20R1%20--%3E%20PAY%5B%22%E9%9A%8F%E6%9C%BA%E6%8A%BD%E4%B8%80%E8%BD%AE%E5%85%91%E7%8E%B0%E6%BF%80%E5%8A%B1%22%5D%0A%20%20R2%20--%3E%20PAY%0A%20%20PAY%20--%3E%20PR%5B%22%E9%A2%84%E6%B3%A8%E5%86%8C%3A%20%E5%81%87%E8%AE%BE%E4%B8%8E%E6%8E%92%E9%99%A4%E8%A7%84%E5%88%99%E5%86%BB%E7%BB%93%22%5D%0A%20%20PR%20--%3E%20DATA%5B%22%E9%87%87%E9%9B%86%E4%B8%8E%E5%88%86%E6%9E%90%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<p><span class="marginnote">数字实例：效应量 \\(d=0.4\\)、80% 功效、5% 显著水平下，被试间设计每组约需 100 人；被试内设计让同一批人自己当对照，个体噪声互相抵消，几十人往往就够。「功效高数倍」不是修辞，是预算表上的样本量差。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>随机化为什么足够：它把被试特征的组间差变成均值零的噪声，处理效应的期望因此干净——这套逻辑下一课被原样搬进田野，交换的只是控制度与真实度。随机抽一轮兑现为什么必要：每题都真付时，被试把整场实验当一个组合去对冲，背景风险污染风险态度——协议正是照主干提示的房子钱账户设计的。诱导价值的样板是拍卖实验：<a href="/econ/winner-curse">共同价值与赢家诅咒</a>的过度叫价与<a href="/econ/all-pay-auction">全支付拍卖</a>的过度竞价，都因价值被诱导、机制被隔离而可定量——没有诱导价值，分不清偏离是偏好还是困惑。策略方法（对每种可能的对手行动都表态）用策略推理的污染换数据密度，直接反应保纯度但样本需求翻倍——选哪一端要写进论文。不这么做会错在哪：不报功效与排除规则的设计，显著结果里混着研究者的自由度——「挖到显著为止」能把任意参数测出来。</p><p><span class="marginnote">「多题作答、随机抽一轮兑现」之所以激励相容：每题在期望意义下都是独立小赌局，诚实报告仍是占优策略，而财富效应只发生一次——风险与时间偏好的测量把它当默认。</span></p><p><span class="marginnote">直觉类比：随机化像洗牌后再发牌——牌技（被试特征）还在，但拿到哪手牌纯靠运气，组间只剩运气差且均值上互相抵消；于是组间差异就能归给「发到了哪手牌」（处理），而不是谁坐庄。</span></p>',5)),(a(),r(i,null,{default:A(()=>[n(B,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%E5%81%87%E8%AE%BE%2C%20%E4%B8%A4%E7%A7%8D%E6%8E%92%E6%B3%95%22%5D%20--%3E%20BW%5B%22%E8%A2%AB%E8%AF%95%E9%97%B4%3A%20%E6%AF%8F%E4%BA%BA%E5%8F%AA%E8%A7%81%E4%B8%80%E7%A7%8D%E5%A4%84%E7%90%86%22%5D%0A%20%20Q%20--%3E%20WI%5B%22%E8%A2%AB%E8%AF%95%E5%86%85%3A%20%E6%AF%8F%E4%BA%BA%E8%BF%87%E5%85%A8%E9%83%A8%E5%A4%84%E7%90%86%22%5D%0A%20%20BW%20--%3E%20K1%5B%22%E4%B9%B0%E5%88%B0%3A%20%E7%BB%84%E9%97%B4%E5%B9%B2%E5%87%80%2C%20%E6%97%A0%20carryover%22%5D%0A%20%20BW%20--%3E%20R1%5B%22%E9%99%A9%E5%9C%A8%3A%20%E7%BB%84%E9%97%B4%E4%B8%8D%E5%8F%AF%E6%AF%94%2C%20%E6%A0%B7%E6%9C%AC%E9%9C%80%E6%B1%82%E5%A4%A7%22%5D%0A%20%20R1%20--%3E%20S1%5B%22%E8%A7%A3%E6%B3%95%3A%20%E9%9A%8F%E6%9C%BA%E5%88%86%E9%85%8D%20%2B%20%E5%B9%B3%E8%A1%A1%E8%A1%A8%22%5D%0A%20%20WI%20--%3E%20K2%5B%22%E4%B9%B0%E5%88%B0%3A%20%E5%8A%9F%E6%95%88%E9%AB%98%E6%95%B0%E5%80%8D%22%5D%0A%20%20WI%20--%3E%20R2%5B%22%E9%99%A9%E5%9C%A8%3A%20%E9%A1%BA%E5%BA%8F%E6%B1%A1%E6%9F%93%E4%B8%8E%E7%96%B2%E5%8A%B3%22%5D%0A%20%20R2%20--%3E%20S2%5B%22%E8%A7%A3%E6%B3%95%3A%20%E6%8B%89%E4%B8%81%E6%96%B9%20%2B%20%E6%B8%85%E6%B4%97%E6%AE%B5%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<p>这张图回答的是：设计选择的交换发生在哪。被试间买「纯度」付「样本量」，被试内买「功效」付「顺序风险」；两种风险的解法（平衡表与拉丁方）都是流程件，不是事后补救——这也是五步协议必须先于数据采集的原因。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>五步协议只管内部有效。实验室之外剩三重折扣，留给下一课：被试池（学生与 WEIRD 样本）、情境（低额与去情境化博弈）、选择集（简化决策树）。欺骗被试是经济学实验的行业禁令：破坏诱导价值的信任前提，代价由此后所有实验分摊。协议本身也是研究对象——前两课的「协议伪影」清单就是设计协议的负样本库。后课默认：拿到任何行为参数，先问五步走到哪一步，再谈数字。</p><p><span class="marginnote">常见误区：把「显著」当「测对了」。题目顺序、报酬方式、实验者在场都能搬动结果；不预注册排除规则，研究者总能在某个子样本里挖出显著——p 值再小，也只证明了自由度存在。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>五步协议：处理结构、随机化、激励、功效、预注册；顺序不能换。</li><li>被试内功效高但要拉丁方与清洗段；被试间干净但吃样本。</li><li>随机抽一轮兑现隔离财富效应；假设性问答只进预实验。</li><li>效应量决定样本量；不报功效的显著结果是自由度的产物。</li><li>内部有效之外的三重折扣——被试、情境、选择集——由现场实验接手。</li><li>出处：Smith, <em>AER</em> 1976、1982；预注册与功效报告按现行实验经济学惯例整理。</li></ul>',6))])}const u=o(p,[["render",d]]);export{f as __pageData,u as default};
